/**
 * Goal vocabulary + call-goal wire-shape parity (D.SDKJS.GOALTYPES.PARITY and
 * the wire-shape rows beneath it).
 *
 * Two questions, each answered from the node's own declarations, vendored as
 * ../goal-vocabulary.json and generated by infrix-core (never hand-edited):
 *
 *   1. VOCABULARY — can a client built from this package NAME exactly the goals
 *      the node accepts, no more and no fewer? A goal missing here cannot be
 *      typed; a goal that is not the node's is refused at admission.
 *   2. WIRE SHAPE — does what each helper EMITS satisfy the node's declaration
 *      for that goal (every required customParams group present, no key the
 *      node refuses by name)? A vocabulary check cannot see this: the goal is
 *      named correctly and refused anyway.
 *
 * The emissions are written to testdata/goal-emissions.json from the real helper
 * output. infrix-core's pkg/release SDKGoalParity fence feeds that file to the
 * node's own admission validator (intent.ValidateGoalParams), so the claim is
 * checked against the validator itself and not against a copy of its rules.
 *
 * Refreshing after an intentional helper change:
 *   INFRIX_UPDATE_GOAL_EMISSIONS=1 node --test dist/goalVocabulary.test.js
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { join, relative } from 'node:path';

import { INTENT_GOAL_TYPES, isIntentGoalType, withGovernanceSugar, InfrixClient } from './index';
import type { InfrixClient as InfrixClientType } from './index';

// dist/goalVocabulary.test.js -> typescript/ -> repo root.
const pkgRoot = join(__dirname, '..');
const vocabularyPath = join(pkgRoot, '..', 'goal-vocabulary.json');
const emissionsPath = join(pkgRoot, 'testdata', 'goal-emissions.json');
const sourceRoot = join(pkgRoot, 'src');

interface GoalDeclaration {
  goal: string;
  class: 'system' | 'custom' | 'asset';
  required: string[][];
  refusedKeys: string[];
}
interface Vocabulary {
  count: number;
  goals: GoalDeclaration[];
}

const vocabulary: Vocabulary = JSON.parse(readFileSync(vocabularyPath, 'utf8'));
const declarations = new Map<string, GoalDeclaration>(vocabulary.goals.map((g) => [g.goal, g]));

function sortedDiff(a: Iterable<string>, b: Set<string>): string[] {
  return [...a].filter((x) => !b.has(x)).sort();
}

// ---------------------------------------------------------------------------
// 1. Vocabulary
// ---------------------------------------------------------------------------

test('the vendored vocabulary is well-formed and non-trivial', () => {
  assert.equal(vocabulary.count, vocabulary.goals.length, 'count disagrees with the list');
  assert.equal(declarations.size, vocabulary.goals.length, 'the vocabulary lists a goal twice');
  assert.ok(vocabulary.goals.length >= 81, `only ${vocabulary.goals.length} goals — the file is not the node's vocabulary`);
});

test('INTENT_GOAL_TYPES is exactly the node vocabulary, in both directions', () => {
  const sdk = new Set<string>(INTENT_GOAL_TYPES);
  assert.equal(sdk.size, INTENT_GOAL_TYPES.length, 'INTENT_GOAL_TYPES lists a goal twice');
  const cannotName = sortedDiff(declarations.keys(), sdk);
  const refused = sortedDiff(sdk, new Set(declarations.keys()));
  assert.deepEqual(cannotName, [], `a typed client cannot name ${cannotName.length} goal(s) the node accepts`);
  assert.deepEqual(refused, [], `the SDK names ${refused.length} goal(s) the node REFUSES`);
});

test('isIntentGoalType accepts every node goal and refuses non-goals', () => {
  for (const g of declarations.keys()) assert.equal(isIntentGoalType(g), true, `${g} should be accepted`);
  // SEND_TOKENS / ADD_CREDITS are transaction kinds the signature explainer
  // describes; SUBMIT_GOVERNED was once scaffolded as a goal. None is a goal.
  for (const bad of ['SEND_TOKENS', 'ADD_CREDITS', 'SUBMIT_GOVERNED', 'contract_call', '', 'CONTRACT_CALL ']) {
    assert.equal(isIntentGoalType(bad), false, `${JSON.stringify(bad)} must be refused`);
  }
  for (const bad of [undefined, null, 7, {}, ['CONTRACT_CALL']]) {
    assert.equal(isIntentGoalType(bad), false);
  }
});

// ---------------------------------------------------------------------------
// 2. Wire shape: the requirement semantics, mirroring the node's
//    GoalFieldSpec.Check / FieldPresent (pkg/intent/goal_params.go).
// ---------------------------------------------------------------------------

function present(params: Record<string, unknown> | undefined, key: string): boolean {
  const v = params?.[key];
  if (v === undefined || v === null) return false;
  if (typeof v === 'string') return v.trim() !== '';
  return true;
}

function groupSatisfied(have: (key: string) => boolean, group: string[]): boolean {
  return group.some((alt) => alt.split('+').every(have));
}

/** Problems with a goal's emitted customParams against the node's declaration. */
function shapeProblems(goal: string, params: Record<string, unknown> | undefined): string[] {
  const decl = declarations.get(goal);
  if (!decl) return [`${goal} is not a goal the node accepts`];
  const problems: string[] = [];
  for (const group of decl.required) {
    if (!groupSatisfied((k) => present(params, k), group)) {
      problems.push(`${goal}: missing required param ${group.length === 1 ? JSON.stringify(group[0]) : 'one of ' + group.join(' | ')}`);
    }
  }
  for (const refused of decl.refusedKeys) {
    if (params && Object.prototype.hasOwnProperty.call(params, refused)) {
      problems.push(`${goal}: the node refuses the key ${JSON.stringify(refused)} by name`);
    }
  }
  return problems;
}

// ---------------------------------------------------------------------------
// 3. Emissions: the real helpers, run.
// ---------------------------------------------------------------------------

interface Emission {
  sdk: 'typescript';
  helper: string;
  goal: { type: string; customParams?: Record<string, unknown> };
}

type FetchLike = (...args: unknown[]) => Promise<unknown>;

function fakeSugarClient(sink: Emission['goal'][]): InfrixClientType {
  const fake = {
    intents: {
      submit: async (goal: Emission['goal']) => {
        sink.push({ type: goal.type, customParams: goal.customParams });
        return { intentId: 'int-1', status: 'submitted', planId: 'plan-1' };
      },
    },
  };
  return fake as unknown as InfrixClientType;
}

async function collectEmissions(): Promise<Emission[]> {
  const out: Emission[] = [];
  const sugarGoals: Emission['goal'][] = [];
  const governed = withGovernanceSugar(fakeSugarClient(sugarGoals));
  const wait = { wait: false } as const;

  const record = (helper: string, goals: Emission['goal'][], from: number) => {
    for (const g of goals.slice(from)) out.push({ sdk: 'typescript', helper, goal: g });
  };

  let mark = sugarGoals.length;
  await governed.deployContract('acc://alice.acme', new Uint8Array([0x00, 0x61, 0x73, 0x6d]), wait);
  record('deployContract', sugarGoals, mark);

  mark = sugarGoals.length;
  await governed.callContract('acc://alice.acme/counter', 'increment', [], wait);
  record('callContract', sugarGoals, mark);

  mark = sugarGoals.length;
  await governed.upgradeContract('acc://alice.acme/counter', new Uint8Array([0x00, 0x61, 0x73, 0x6d]), wait);
  record('upgradeContract', sugarGoals, mark);

  mark = sugarGoals.length;
  await governed.createObject('budget_approval', { action: 'approve-budget' }, wait);
  record('createObject', sugarGoals, mark);

  mark = sugarGoals.length;
  await governed.grantCapability(
    'acc://bob.acme',
    ['token:transfer'],
    { workflowStageScope: '*', purpose: 'operational', contractUrl: 'acc://alice.acme/counter' },
    wait,
  );
  record('grantCapability', sugarGoals, mark);

  // client.evm.* submits through the JSON-RPC transport; capture what it sends.
  const realFetch = (globalThis as { fetch?: FetchLike }).fetch;
  const wire: Array<{ goalType: string; customParams?: Record<string, unknown> }> = [];
  (globalThis as { fetch?: FetchLike }).fetch = async (_url: unknown, init: unknown) => {
    const body = JSON.parse((init as { body: string }).body);
    wire.push({ goalType: body.params.goalType, customParams: body.params.customParams });
    return { json: async () => ({ result: { intentId: 'i-1', status: 'pending' } }) };
  };
  try {
    const c = new InfrixClient('http://node.test', { actor: 'acc://alice.acme', purpose: 'test' });
    await c.evm.deploy('0x60806040', { authority: 'acc://alice.acme' });
    await c.evm.call('acc://alice.acme/evm-1', '0x70a08231');
  } finally {
    (globalThis as { fetch?: FetchLike }).fetch = realFetch;
  }
  out.push({ sdk: 'typescript', helper: 'evm.deploy', goal: { type: wire[0].goalType, customParams: wire[0].customParams } });
  out.push({ sdk: 'typescript', helper: 'evm.call', goal: { type: wire[1].goalType, customParams: wire[1].customParams } });
  return out;
}

test('every goal a helper emits satisfies the node declaration for that goal', async () => {
  const emissions = await collectEmissions();
  assert.ok(emissions.length >= 7, 'the helpers emitted fewer goals than expected, so the check is not exercising them');
  const problems = emissions.flatMap((e) => shapeProblems(e.goal.type, e.goal.customParams).map((p) => `${e.helper}: ${p}`));
  assert.deepEqual(problems, [], 'a helper emits a goal the node refuses at admission');
});

test('goal-emissions.json is what the helpers emit now (infrix-core feeds it to the node validator)', async () => {
  const emissions = await collectEmissions();
  const doc = { emissions };
  const rendered = JSON.stringify(doc, null, 2) + '\n';
  if (process.env.INFRIX_UPDATE_GOAL_EMISSIONS === '1') writeFileSync(emissionsPath, rendered);
  const onDisk = JSON.parse(readFileSync(emissionsPath, 'utf8'));
  assert.deepEqual(
    onDisk,
    JSON.parse(rendered),
    'testdata/goal-emissions.json is stale: re-run with INFRIX_UPDATE_GOAL_EMISSIONS=1 and let infrix-core re-check it',
  );
});

test('grantCapability states workflowStageScope and purpose, and refuses to invent them', async () => {
  const sink: Emission['goal'][] = [];
  const governed = withGovernanceSugar(fakeSugarClient(sink));
  const wait = { wait: false } as const;
  await assert.rejects(
    () => (governed.grantCapability as unknown as (...a: unknown[]) => Promise<unknown>)('acc://bob.acme', ['x'], undefined, wait),
    /workflowStageScope .* and\s+scope\.purpose .* are required/s,
  );
  await assert.rejects(
    () => (governed.grantCapability as unknown as (...a: unknown[]) => Promise<unknown>)('acc://bob.acme', ['x'], { purpose: 'audit' }, wait),
    /required/,
  );
  assert.equal(sink.length, 0, 'a grant with no stated scope must not reach the node');
  await governed.grantCapability('acc://bob.acme', ['x'], { workflowStageScope: 'approve', purpose: 'audit' }, wait);
  assert.deepEqual(sink[0].customParams, { granteeId: 'acc://bob.acme', capabilities: ['x'], workflowStageScope: 'approve', purpose: 'audit' });
});

// ---------------------------------------------------------------------------
// 4. Every goal literal in the SDK's own source (code, doc examples and the
//    scaffold templates) names a goal the node accepts and carries its
//    required keys.
// ---------------------------------------------------------------------------

interface GoalLiteral {
  goal: string;
  /** Top-level keys of an inline `customParams: { ... }`, or null when the params are not an inline literal. */
  keys: string[] | null;
  line: number;
}

function stripDocPrefix(text: string): string {
  return text.replace(/^[ \t]*\*[ \t]?/gm, '');
}

/** Split an object-literal body into its top-level keys. Returns null on a spread. */
function topLevelKeys(body: string): string[] | null {
  const keys: string[] = [];
  let depth = 0;
  let quote = '';
  let part = '';
  const flush = (): boolean => {
    const t = part.trim();
    part = '';
    if (t === '') return true;
    if (t.startsWith('...')) return false;
    const m = /^(?:'([^']+)'|"([^"]+)"|([A-Za-z_$][\w$]*))/.exec(t);
    if (!m) return false;
    keys.push(m[1] ?? m[2] ?? m[3]);
    return true;
  };
  for (let i = 0; i < body.length; i++) {
    const c = body[i];
    if (quote) {
      part += c;
      if (c === '\\') part += body[++i] ?? '';
      else if (c === quote) quote = '';
      continue;
    }
    if (c === "'" || c === '"' || c === '`') {
      quote = c;
      part += c;
      continue;
    }
    if (c === '{' || c === '[' || c === '(') depth++;
    if (c === '}' || c === ']' || c === ')') depth--;
    if (c === ',' && depth === 0) {
      if (!flush()) return null;
      continue;
    }
    part += c;
  }
  return flush() ? keys : null;
}

function scanGoalLiterals(source: string): GoalLiteral[] {
  const found: GoalLiteral[] = [];
  const re = /\b(?:type|goalType):\s*['"]([A-Z][A-Z0-9_]*)['"]/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(source)) !== null) {
    const line = source.slice(0, m.index).split('\n').length;
    const tail = source.slice(m.index + m[0].length);
    const lead = /^\s*(?:as\s+[A-Za-z_$][\w$]*\s*)?,\s*(?:\*\s*)?customParams:\s*\{/.exec(stripDocPrefix(tail.slice(0, 200)));
    if (!lead) {
      found.push({ goal: m[1], keys: null, line });
      continue;
    }
    // Brace-match from the opening brace of customParams in the ORIGINAL text.
    const open = tail.indexOf('{', tail.search(/customParams:/));
    let depth = 0;
    let end = -1;
    for (let i = open; i < tail.length; i++) {
      if (tail[i] === '{') depth++;
      else if (tail[i] === '}' && --depth === 0) {
        end = i;
        break;
      }
    }
    found.push({ goal: m[1], keys: end < 0 ? null : topLevelKeys(stripDocPrefix(tail.slice(open + 1, end))), line });
  }
  return found;
}

function literalProblems(file: string, literals: GoalLiteral[], covered: Set<string>): string[] {
  const problems: string[] = [];
  for (const lit of literals) {
    const where = `${file}:${lit.line} ${lit.goal}`;
    const decl = declarations.get(lit.goal);
    if (!decl) {
      problems.push(`${where}: not a goal the node accepts`);
      continue;
    }
    if (lit.keys === null) {
      // Params are built dynamically; a helper's emission must cover this goal.
      if (decl.required.length > 0 && !covered.has(lit.goal)) {
        problems.push(`${where}: customParams is not an inline literal and no emission covers ${lit.goal}, so its shape is unchecked`);
      }
      continue;
    }
    const have = new Set(lit.keys);
    for (const group of decl.required) {
      if (!groupSatisfied((k) => have.has(k), group)) {
        problems.push(`${where}: customParams lacks ${group.join(' | ')}`);
      }
    }
    for (const refused of decl.refusedKeys) {
      if (have.has(refused)) problems.push(`${where}: customParams uses ${refused}, which the node refuses by name`);
    }
  }
  return problems;
}

/** Documentation and example files across the repo (READMEs, runnable examples). */
function docFiles(dir: string, out: string[] = []): string[] {
  const skip = new Set(['node_modules', 'dist', 'build', 'test-dist', '.git', '.github', 'tools', 'release']);
  for (const name of readdirSync(dir)) {
    const full = join(dir, name);
    if (statSync(full).isDirectory()) {
      if (!skip.has(name)) docFiles(full, out);
    } else if (name.endsWith('.md') || name.endsWith('.mjs')) {
      out.push(full);
    }
  }
  return out;
}

function sourceFiles(dir: string): string[] {
  const out: string[] = [];
  for (const name of readdirSync(dir)) {
    const full = join(dir, name);
    if (statSync(full).isDirectory()) out.push(...sourceFiles(full));
    else if (name.endsWith('.ts') && !name.endsWith('.test.ts') && !name.endsWith('.d.ts')) out.push(full);
  }
  return out;
}

test('every goal literal in the SDK source is a node goal with its required keys', async () => {
  const covered = new Set((await collectEmissions()).map((e) => e.goal.type));
  const problems: string[] = [];
  let scanned = 0;
  for (const file of sourceFiles(sourceRoot)) {
    const literals = scanGoalLiterals(readFileSync(file, 'utf8'));
    scanned += literals.length;
    problems.push(...literalProblems(relative(sourceRoot, file).replace(/\\/g, '/'), literals, covered));
  }
  assert.ok(scanned >= 8, `the scanner found only ${scanned} goal literals, so it is not reading the source`);
  assert.deepEqual(problems, []);
});

test('every goal literal in the READMEs and runnable examples is a node goal with its required keys', async () => {
  const covered = new Set((await collectEmissions()).map((e) => e.goal.type));
  const repoRoot = join(pkgRoot, '..');
  const problems: string[] = [];
  let scanned = 0;
  for (const file of docFiles(repoRoot)) {
    const literals = scanGoalLiterals(readFileSync(file, 'utf8'));
    scanned += literals.length;
    problems.push(...literalProblems(relative(repoRoot, file).replace(/\\/g, '/'), literals, covered));
  }
  assert.ok(scanned >= 1, 'the scanner found no goal literal in any README or example, so it is not reading them');
  assert.deepEqual(problems, []);
});

test('the literal scanner is not blind: it flags a refused goal, a misnamed key, and an uncovered dynamic shape', () => {
  const none = new Set<string>();
  const flagged = (src: string) => literalProblems('planted.ts', scanGoalLiterals(src), none);

  // The scaffold once submitted a goal the node refuses.
  assert.match(flagged(`{ type: 'SUBMIT_GOVERNED', customParams: { action: 'x' } }`).join('\n'), /not a goal the node accepts/);
  // The Rust SDK's defect: the call target under "method" rather than "function".
  assert.match(
    flagged(`{ type: 'CONTRACT_CALL', customParams: { contract: 'acc://a.acme', method: 'go' } }`).join('\n'),
    /lacks function/,
  );
  // A multi-line, doc-comment example is read too.
  assert.match(
    flagged(` *   type: 'CONTRACT_CALL',\n *   customParams: {\n *     contract: 'acc://a.acme',\n *     method: 'go',\n *   },`).join('\n'),
    /lacks function/,
  );
  // A key the node refuses by name.
  assert.match(
    flagged(`{ type: 'WORKFLOW_START', customParams: { definitionId: 'd', workflowId: 'w' } }`).join('\n'),
    /refuses by name/,
  );
  // A dynamic shape with no covering emission is reported, not assumed fine.
  assert.match(flagged(`{ type: 'CAPABILITY_GRANT', customParams }`).join('\n'), /unchecked/);
  // The correct shapes are not flagged (otherwise the cases above prove nothing).
  assert.deepEqual(flagged(`{ type: 'CONTRACT_CALL', customParams: { contract: 'a', function: 'f', args: '[]' } }`), []);
  assert.deepEqual(flagged(`{ type: 'CONTRACT_DEPLOY' as IntentGoalType, customParams: { authority, bytecode: toHex(wasm) } }`), []);
  assert.deepEqual(flagged(`{ goalType: 'EVM_CALL', customParams: { contract, calldata: x } }`), []);
});

test('shapeProblems flags what the Rust SDK got wrong and what the TypeScript grant omitted', () => {
  assert.deepEqual(shapeProblems('CONTRACT_CALL', { contract: 'acc://a.acme', function: 'go' }), []);
  assert.match(shapeProblems('CONTRACT_CALL', { contract: 'acc://a.acme', method: 'go' }).join('\n'), /missing required param "function"/);
  assert.match(shapeProblems('CONTRACT_CALL', undefined).join('\n'), /missing required param "contract"/);
  assert.match(shapeProblems('CONTRACT_CALL', { contract: 'acc://a.acme', function: '   ' }).join('\n'), /"function"/);
  assert.match(
    shapeProblems('CAPABILITY_GRANT', { granteeId: 'g', capabilities: ['c'] }).join('\n'),
    /workflowStageScope[\s\S]*purpose/,
  );
  assert.match(shapeProblems('SEND_TOKENS', {}).join('\n'), /not a goal the node accepts/);
});
